                    p.Add("movebetsday", ReportUtils.BalanceUp.BalanceUpDay);
                    using (var db = new ObjectDb("BetList_CustInfo", 180))
                    {
                        db.AssignParamValues(p);
                        rs = db.ExecuteDataSet();
                    }
                }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }
            return rs;
        }

